# If we have any specifiers, then we want to consider the complete
# intersection of all specifiers when deciding whether prereleases
# should be allowed under the automatic policy. An out-of-range final
# release must not suppress matching prereleases.
if self._specs:
    if prereleases is None:
        filtered: list[UnparsedVersionVar] = []
        found_prereleases: list[UnparsedVersionVar] = []

        for item in iterable:
            parsed_version = _coerce_version(item)

            if all(
                spec.contains(parsed_version, prereleases=True)
                for spec in self._specs
            ):
                if parsed_version.is_prerelease:
                    found_prereleases.append(item)
                else:
                    filtered.append(item)

        # Only fall back to prereleases if no matching final (or
        # post) release exists in the intersection.
        if filtered:
            return iter(filtered)
        return iter(found_prereleases)

    # With an explicit prereleases policy, wrap our iterable in the
    # filter method for each specifier, acting as a logical AND.
    for spec in self._specs:
        iterable = spec.filter(iterable, prereleases=bool(prereleases))
    return iter(iterable)

